1	'use client';
2	
3	import Image from 'next/image';
4	import { useCallback, useEffect, useState } from 'react';
5	import useEmblaCarousel from 'embla-carousel-react';
6	import styles from './portfolio-carousel.module.css';
7	
8	interface Slide {
9	  label: string;
10	  labelVariant: string;
11	  cardVariant: string;
12	  imageOuterVariant: string;
13	  imageSrc: string;
14	  imageAlt: string;
15	  imageWidth: number;
16	  imageHeight: number;
17	}
18	
19	const SLIDES: Slide[] = [
20	  {
21	    label: 'Shopify',
22	    labelVariant: 'heading-3-green',
23	    cardVariant: 'cream',
24	    imageOuterVariant: 'green',
25	    imageSrc: '/images/webflow/69662a202a4c0d57bdf2c10b_Home.png',
26	    imageAlt: 'Portfolio Image',
27	    imageWidth: 843,
28	    imageHeight: 690,
29	  },
30	  {
31	    label: 'WordPress',
32	    labelVariant: 'heading-3-green-light',
33	    cardVariant: 'light-green',
34	    imageOuterVariant: 'green-light',
35	    imageSrc: '/images/webflow/Travel.png',
36	    imageAlt: 'TravelPerk corporate travel management website template built by Boldteq',
37	    imageWidth: 840,
38	    imageHeight: 690,
39	  },
40	  {
41	    label: 'Figma UI/UX Design',
42	    labelVariant: 'heading-3-purple',
43	    cardVariant: 'light-purple',
44	    imageOuterVariant: 'orange-light',
45	    imageSrc: '/images/webflow/Home-1.png',
46	    imageAlt: 'Dynamic lifestyle brand website template built by Boldteq',
47	    imageWidth: 843,
48	    imageHeight: 690,
49	  },
50	  {
51	    label: 'Banners',
52	    labelVariant: 'heading-3-orange',
53	    cardVariant: 'light-orange',
54	    imageOuterVariant: 'olive-green',
55	    imageSrc: '/images/webflow/Group-7.png',
56	    imageAlt: 'Beauty and skincare product website template built by Boldteq',
57	    imageWidth: 807,
58	    imageHeight: 690,
59	  },
60	];
61	
62	// Duplicate for seamless loop
63	const ALL_SLIDES = [...SLIDES, ...SLIDES];
64	
65	export function PortfolioCarousel() {
66	  const [emblaRef, emblaApi] = useEmblaCarousel({
67	    loop: true,
68	    align: 'start',
69	    dragFree: false,
70	    slidesToScroll: 1,
71	  });
72	  const [selectedIndex, setSelectedIndex] = useState(0);
73	
74	  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
75	  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);
76	  const scrollTo = useCallback((i: number) => emblaApi?.scrollTo(i), [emblaApi]);
77	
78	  useEffect(() => {
79	    if (!emblaApi) return;
80	    const onSelect = () => setSelectedIndex(emblaApi.selectedScrollSnap() % SLIDES.length);
81	    emblaApi.on('select', onSelect);
82	    onSelect();
83	    return () => { emblaApi.off('select', onSelect); };
84	  }, [emblaApi]);
85	
86	  return (
87	    <section
88	      className={`${styles['section-regular-2']} ${styles['img-slider-sec']}`}
89	    >
90	      <div className={styles['column-4x-large']} style={{ alignItems: 'center' }}>
91	        {/* Slider container — relative for arrow positioning */}
92	        <div style={{ position: 'relative', width: '100%' }}>
93	          {/* Embla viewport */}
94	          <div ref={emblaRef} className={styles['gallery-13-mask']}>
95	            {/* Track */}
96	            <div style={{ display: 'flex', gap: '24px', height: 'auto' }}>
97	              {ALL_SLIDES.map((slide, i) => (
98	                <div
99	                  key={`${slide.label}-${i}`}
100	                  className={styles['gallery-13-slide']}
101	                >
102	                  <div
103	                    className={`${styles['gallery-13-card']} ${styles[slide.cardVariant]}`}
104	                  >
105	                    {/* Image outer */}
106	                    <div
107	                      className={`${styles['gallery-image-outer']} ${styles[slide.imageOuterVariant]}`}
108	                    >
109	                      <Image
110	                        src={slide.imageSrc}
111	                        alt={slide.imageAlt}
112	                        width={slide.imageWidth}
113	                        height={slide.imageHeight}
114	                        loading="lazy"
115	                        className={`${styles['image-cover']} ${styles['radius-0']}`}
116	                      />
117	                    </div>
118	                    {/* Caption */}
119	                    <div className={styles['gallery-13-caption']}>
120	                      <div className={`${styles['heading-3']} ${styles[slide.labelVariant]}`}>
121	                        {slide.label}
122	                      </div>
123	                    </div>
124	                  </div>
125	                </div>
126	              ))}
127	            </div>
128	          </div>
129	
130	          {/* Prev button */}
131	          <button
132	            onClick={scrollPrev}
133	            aria-label="Previous slide"
134	            className={`${styles['gallery-13-button']} ${styles['button-left']}`}
135	            style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer' }}
136	          >
137	            <div className={styles['icon-button-outline-large']}>
138	              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
139	                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
140	                  <path d="M7.82843 10.9999H20V12.9999H7.82843L13.1924 18.3638L11.7782 19.778L4 11.9999L11.7782 4.22168L13.1924 5.63589L7.82843 10.9999Z" fill="currentColor" />
141	                </svg>
142	              </span>
143	            </div>
144	          </button>
145	
146	          {/* Next button */}
147	          <button
148	            onClick={scrollNext}
149	            aria-label="Next slide"
150	            className={`${styles['gallery-13-button']} ${styles['button-right']}`}
151	            style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer' }}
152	          >
153	            <div className={styles['icon-button-outline-large']}>
154	              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
155	                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
156	                  <path d="M16.1716 10.9999L10.8076 5.63589L12.2218 4.22168L20 11.9999L12.2218 19.778L10.8076 18.3638L16.1716 12.9999H4V10.9999H16.1716Z" fill="currentColor" />
157	                </svg>
158	              </span>
159	            </div>
160	          </button>
161	        </div>
162	
163	        {/* Dot navigation */}
164	        <div
165	          style={{
166	            justifyContent: 'flex-start',
167	            alignItems: 'center',
168	            maxWidth: 'calc(100% - 112px)',
169	            marginLeft: 0,
170	            paddingTop: '16px',
171	            paddingBottom: '16px',
172	            display: 'flex',
173	            gap: '4px',
174	          }}
175	        >
176	          {SLIDES.map((_, i) => (
177	            <button
178	              key={i}
179	              onClick={() => scrollTo(i)}
180	              aria-label={`Go to slide ${i + 1}`}
181	              style={{
182	                height: '12px',
183	                width: '12px',
184	                borderRadius: '50%',
185	                border: 'none',
186	                cursor: 'pointer',
187	                transition: 'background-color 0.2s',
188	                backgroundColor: i === selectedIndex ? '#000' : '#EDF0F2',
189	                marginBottom: 0,
190	                padding: 0,
191	                flexShrink: 0,
192	              }}
193	            />
194	          ))}
195	        </div>
196	      </div>
197	
198	      <div className={styles['container-large-2']} />
199	    </section>
200	  );
201	}
